static void Native(Renderer root,Color tint){var renderers=root.GetComponentsInChildren<Renderer>(true);var material=renderers[0].material;material.color=tint;for(int i=1;i<renderers.Length;i++)if(renderers[i].CompareTag("LOD")&&renderers[i].sharedMaterials.Length==1)renderers[i].sharedMaterial=material;}
static Vector3 Mean(Renderer r,Camera cam,RenderTexture rt){var b=r.bounds;Vector3 normal=r.name.Contains("Tail")||r.name.Contains("tail")||r.name.Contains("lens")||r.name.Contains("flute")?Vector3.back:r.name.Contains("floor")?Vector3.up:(r.name=="Painted bed front corner 1"?Vector3.left:Vector3.right);
cam.transform.position=b.center+normal*10;cam.transform.LookAt(b.center);cam.orthographicSize=Mathf.Max(b.size.x,Mathf.Max(b.size.y,b.size.z))*.65f+.02f;r.enabled=true;cam.Render();r.enabled=false;var previous=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(256,256,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,256,256),0,0);tex.Apply();Vector3 sum=Vector3.zero;int count=0;foreach(var c in tex.GetPixels())if(c.maxColorComponent>.01){sum+=new Vector3(c.r,c.g,c.b);count++;}RenderTexture.active=previous;Object.DestroyImmediate(tex);return count==0?Vector3.zero:sum/count;}
public static void Run(){Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var bundle=AssetBundle.LoadFromFile("C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/Mods/zzz_REBIRTH__3_0/Resources/rebirth_camper80s.unity3d");var root=Object.Instantiate(bundle.LoadAsset<GameObject>("rebirthCamper80s"));foreach(var r in root.GetComponentsInChildren<Renderer>(true).Where(r=>r.name.Contains("RearRedLenses")))log.AppendLine("LIGHT "+r.name+" path="+r.transform.parent.name+" materials="+string.Join(";",r.sharedMaterials.Select(m=>m.name+":"+m.shader.name+":emission="+m.HasProperty("_EmissionColor"))));var body=root.transform.Find("GameObject/M/VisualBody/80sCamperTruck/body").GetComponent<Renderer>();var paint=body.transform.Find("REBIRTHPickupOnlyPaint");var added=paint.GetComponentsInChildren<Renderer>(true);foreach(var r in added)log.AppendLine("ADDED "+r.name+" tag="+r.tag+" slots="+r.sharedMaterials.Length+" shader="+r.sharedMaterial.shader.name+" color="+r.sharedMaterial.color);foreach(var r in root.GetComponentsInChildren<Renderer>(true))r.enabled=false;
var floor=root.GetComponentsInChildren<Renderer>(true).First(r=>r.name=="Continuous pressed load floor - native tub cutouts");var go=new GameObject("audit-camera");var cam=go.AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.orthographic=true;var rt=new RenderTexture(256,256,24);cam.targetTexture=rt;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var light=new GameObject("light").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(35,-25,0);light.intensity=1;
foreach(var color in new[]{new Color(255,0,0,1),new Color(0,0,255,1),new Color(255,255,255,1)}){Native(body,color);foreach(var panel in added){panel.sharedMaterial=new Material(panel.sharedMaterial);panel.sharedMaterial.color=new Color(255,255,255,1);var mpb=new MaterialPropertyBlock();panel.GetPropertyBlock(mpb);mpb.SetColor("_Color",color);panel.SetPropertyBlock(mpb);}foreach(var r in added){r.gameObject.SetActive(true);log.AppendLine("PIXEL "+color+" "+r.name+" material="+r.sharedMaterial.color+" avg="+Mean(r,cam,rt));}log.AppendLine("FLOOR "+color+" material="+floor.sharedMaterial.color+" avg="+Mean(floor,cam,rt));}
var template=root.GetComponentsInChildren<Renderer>(true).First(r=>r.name=="RearRedLenses").sharedMaterial;
foreach(var lens in root.GetComponentsInChildren<Renderer>(true).Where(r=>RebirthCamperLampIntensity.PickupLens(r.name,out _)).Where(r=>r.name=="Rear lamp lens segment"||r.name=="Rear lamp lens segment.002")){RebirthCamperLampIntensity.PickupLens(lens.name,out bool reverse);lens.sharedMaterial=new Material(template);foreach(float intensity in new[]{0f,.65f}){var mpb=new MaterialPropertyBlock();mpb.SetColor("_EmissionColor",(reverse?Color.white:Color.red)*intensity);lens.SetPropertyBlock(mpb);log.AppendLine("LAMP "+lens.name+" reverse="+reverse+" intensity="+intensity+" mean="+Mean(lens,cam,rt));}}
File.WriteAllText(Output+"/dye-audit.txt",log.ToString());Debug.Log("DYE_AUDIT_COMPLETE");Object.DestroyImmediate(root);Object.DestroyImmediate(go);Object.DestroyImmediate(light.gameObject);Object.DestroyImmediate(rt);bundle.Unload(true);}}
